const ELEMENT_PROP_KEYS = new Set(["theme","title","caption","slit","accent","barColor","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  title: "Now showing.",
  caption: "A launch film, built in React.",
  slit: 0.125,
  accent: "#3B5BFD",
  barColor: "#0A0A0B",
  fontFamily: "Instrument Serif",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type AspectSlitElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof AspectSlitBase>;

const AspectSlitInner = forwardRef<
  HTMLDivElement,
  AspectSlitElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<AspectSlit>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <AspectSlitBase
          {...(componentProps as unknown as ComponentProps<typeof AspectSlitBase>)}
        />
      </div>
    </Sequence>
  );
});

